automatically_repaired_code:
total_cost = 0
for file in electricity_bills:
    file_content = apis.file_system.show_file(file_path=file, access_token=<REDACTED:CREDENTIAL:SHA256=f542cec32c125ef1c0417e3dfcceb11c888f2a9f70c2c74265864412c0b7e859>'access_token'])
    content = file_content['content']
    # Check if the file is a text file by checking if content is a string
    if isinstance(content, str):
        total_amount_line = next((line for line in content.split('\n') if 'Total Amount' in line), None)
        if total_amount_line:
            total_amount = float(total_amount_line.split('=>')[1].strip().replace('$', ''))
            total_cost += total_amount
        else:
            print(f"Warning: Total Amount line not found in text file: {file}")
    else:
        print(f"Skipping binary file: {file}")

print(f"Total cost of electricity bills for this year: ${total_cost:.2f}")

